def seed_database(db):
    if db.execute("SELECT count(*) FROM users").fetchone()[0]:
        return
    for name in ["Анастасия", "Михаил", "Алина", "Илья", "Даниил", "София"]:
        db.execute("INSERT INTO users(name,email,password_hash,group_name,bio) VALUES(?,?,?,?,?)", (name, f"demo-{name}@example.invalid", "", "ТОП-107Б", "Делюсь знаниями и собираю полезное к сессии."))
    for i, (title,description,subject,kind,topic,label,author,rating,downloads) in enumerate(DEMO_MATERIALS,1):
        db.execute("""INSERT INTO materials(id,title,description,subject,course,semester,kind,topic,author_id,
                      format_label,rating,downloads,created_at,demo,external_url)
                      VALUES(?,?,?,?,1,1,?,?,?,?,?,?,?,1,?)""", (i,title,description,subject,kind,topic,author,label,rating,downloads,"2026-11-08T12:00:00", "https://react.dev/learn/your-first-component" if i==7 else None))
    for title,description,topic in BOOKS:
        db.execute("""INSERT INTO materials(title,description,subject,course,semester,kind,topic,author_id,
          format_label,created_at,content) VALUES(?,?,'Математика',1,1,'Конспект',?,1,?,?,?)""", (title,description,topic,"Рекомендация · из матан.md", "2026-11-07T12:00:00", description + "\n\nЭто рекомендация из подборки материалов по матанализу. Полный текст книги и ссылка на скачивание не предоставлены."))
    for title,desc,ids in [
        ("Математика: пределы и производные", "База по матрицам и пределам для подготовки к контрольной.", [2,5]),
        ("C++: массивы и циклы", "Конспект и практика по массивам и алгоритмам поиска.", [1,4]),
    ]:
        cursor = db.execute("INSERT INTO collections(title,description,user_id,created_at,demo) VALUES(?,?,1,?,1)", (title,desc,"2026-11-08T12:00:00"))
        db.executemany("INSERT INTO collection_items VALUES(?,?)", [(cursor.lastrowid,i) for i in ids])
    for user_id,body in [(2,"Наконец разобрался с индексами. Примеры очень помогли перед парой!"),(3,"Всё коротко и понятно. Спасибо за разбор задач.")]:
        db.execute("INSERT INTO reviews(material_id,user_id,rating,body,created_at) VALUES(1,?,5,?,?)", (user_id,body,"2026-11-09T12:00:00"))
